[metadata] {"type": "create", "filePath": "/workspace/repo/codex-rs/test-binary-support/lib.rs", "content": "//! Shared test-support helpers for configuring arg0 dispatch inside test
//! binaries.
//!
//! Integration test binaries across the workspace want to behave like the real
//! `codex` executable: they must dispatch to `apply_patch`,
//! `codex-linux-sandbox`, and friends based on `argv[0]`/`argv[1]`, and they
//! must install the arg0 alias directory on `PATH` before any test threads are
//! spawned. This crate centralizes that setup so each test binary only needs a
//! small `#[ctor]` shim that delegates to
//! [`configure_test_binary_dispatch`].

use std::ffi::OsString;
use std::path::Path;

use codex_arg0::Arg0DispatchPaths;
use codex_arg0::Arg0PathEntryGuard;
use codex_arg0::arg0_dispatch;
use codex_arg0::prepend_path_entry_for_codex_aliases;
use tempfile::TempDir;

const CODEX_HOME_ENV_VAR: &str = "CODEX_HOME";

/// Guard returned by [`configure_test_binary_dispatch`] when arg0 aliases are
/// installed. It keeps the temporary `CODEX_HOME` directory and the arg0 path
/// entry alive for the lifetime of the test binary.
pub struct TestBinaryDispatchGuard {
    _codex_home: TempDir,
    arg0: Arg0PathEntryGuard,
}

impl TestBinaryDispatchGuard {
    /// Paths to the helper executables installed for this test binary.
    pub fn paths(&self) -> &Arg0DispatchPaths {
        self.arg0.paths()
    }
}

/// Controls what [`configure_test_binary_dispatch`] does for the current
/// process invocation. Returned by the `classify` closure.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TestBinaryDispatchMode {
    /// Dispatch via arg0 (e.g. `apply_patch`) and return `None`; no aliases are
    /// installed for the current process.
    DispatchArg0Only,
    /// Do nothing and return `None`. Used for helper re-execs (such as
    /// `codex-linux-sandbox`) that must not create another `CODEX_HOME`.
    Skip,
    /// Set up a temporary `CODEX_HOME`, install the arg0 dispatch aliases,
    /// restore the previous `CODEX_HOME`, and return a guard.
    InstallAliases,
}

/// Configure arg0 dispatch for a test binary.
///
/// Reads `argv[0]` (as a file name) and `argv[1]`, hands both to `classify` to
/// determine the [`TestBinaryDispatchMode`], and acts accordingly:
///
/// * [`TestBinaryDispatchMode::DispatchArg0Only`] runs [`arg0_dispatch`] and
///   returns `None`.
/// * [`TestBinaryDispatchMode::Skip`] returns `None` without touching the
///   environment.
/// * [`TestBinaryDispatchMode::InstallAliases`] creates a temporary
///   `CODEX_HOME` (named with `codex_home_prefix`), installs the arg0 aliases
///   under it, restores the previous `CODEX_HOME`, and returns a
///   [`TestBinaryDispatchGuard`].
///
/// This is intended to be called from a `#[ctor]` static initializer, before
/// any test threads are spawned, so mutating the process environment is safe.
pub fn configure_test_binary_dispatch<F>(
    codex_home_prefix: &str,
    classify: F,
) -> Option<TestBinaryDispatchGuard>
where
    F: FnOnce(&str, Option<&str>) -> TestBinaryDispatchMode,
{
    let mut args = std::env::args_os();
    let argv0 = args.next().unwrap_or_default();
    let exe_name = Path::new(&argv0)
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("");
    let argv1 = args.next().unwrap_or_default();
    let argv1 = argv1.to_str();

    match classify(exe_name, argv1) {
        TestBinaryDispatchMode::DispatchArg0Only => {
            let _ = arg0_dispatch();
            None
        }
        TestBinaryDispatchMode::Skip => None,
        TestBinaryDispatchMode::InstallAliases => install_aliases(codex_home_prefix),
    }
}

fn install_aliases(codex_home_prefix: &str) -> Option<TestBinaryDispatchGuard> {
    let codex_home = tempfile::Builder::new()
        .prefix(codex_home_prefix)
        .tempdir()
        .ok()?;

    // `prepend_path_entry_for_codex_aliases` places helper links under
    // `CODEX_HOME/tmp`. Point it at the test-owned temp dir so startup never
    // mutates the developer's real `~/.codex`.
    let previous_codex_home = std::env::var_os(CODEX_HOME_ENV_VAR);
    // Safety: this runs before tests start (from a `#[ctor]`), so no test
    // threads exist yet.
    unsafe {
        std::env::set_var(CODEX_HOME_ENV_VAR, codex_home.path());
    }

    let arg0 = prepend_path_entry_for_codex_aliases();

    // Restore the process environment immediately so later tests observe the
    // same `CODEX_HOME` state they started with.
    restore_codex_home(previous_codex_home);

    let arg0 = arg0.ok()?;
    Some(TestBinaryDispatchGuard {
        _codex_home: codex_home,
        arg0,
    })
}

fn restore_codex_home(previous_codex_home: Option<OsString>) {
    // Safety: see `install_aliases`; the process is still single-threaded.
    match previous_codex_home {
        Some(value) => unsafe {
            std::env::set_var(CODEX_HOME_ENV_VAR, value);
        },
        None => unsafe {
            std::env::remove_var(CODEX_HOME_ENV_VAR);
        },
    }
}
